import { getCurrentUserId, getTenantId, supabase } from '@/lib/supabase'

// ============================================================
// Types
// ============================================================

export interface AvailabilitySchedule {
  id: string
  tenant_id: string
  therapist_id: string
  day_of_week: number // 0=Domingo, 6=Sábado
  start_time: string // HH:MM:SS
  end_time: string
  is_active: boolean
  created_at: string | null
}

export interface AvailabilityInput {
  day_of_week: number
  start_time: string
  end_time: string
  is_active?: boolean
}

export interface BookingService {
  id: string
  tenant_id: string
  therapist_id: string | null
  module_id: string | null
  name: string
  description: string | null
  duration_minutes: number
  buffer_minutes: number
  price: number | null
  color: string | null
  is_active: boolean
  display_order: number
  created_at: string | null
}

export interface BookingServiceInput {
  module_id?: string | null
  name: string
  description?: string | null
  duration_minutes: number
  buffer_minutes?: number
  price?: number | null
  color?: string
  is_active?: boolean
  display_order?: number
}

// Módulo de terapia para listagem no booking
export interface BookableModule {
  id: string
  name: string
  description: string | null
  icon: string | null
  color: string | null
  active: boolean
  // Dados do booking_service vinculado (se existir)
  booking_service?: {
    id: string
    is_active: boolean
    duration_minutes: number
    buffer_minutes: number
    price: number | null
  } | null
}

// ============================================================
// Availability Schedules
// ============================================================

export async function getAvailabilitySchedules(): Promise<AvailabilitySchedule[]> {
  const tenantId = await getTenantId()
  if (!tenantId) return []
  const therapistId = await getCurrentUserId()

  const { data, error } = await supabase
    .from('availability_schedules')
    .select('*')
    .eq('tenant_id', tenantId)
    .eq('therapist_id', therapistId)
    .order('day_of_week')
    .order('start_time')

  if (error) throw error
  return data || []
}

export async function createAvailabilitySchedule(
  input: AvailabilityInput
): Promise<AvailabilitySchedule> {
  const tenantId = await getTenantId()
  if (!tenantId) throw new Error('Tenant não encontrado')
  const therapistId = await getCurrentUserId()

  const { data, error } = await supabase
    .from('availability_schedules')
    .insert({
      tenant_id: tenantId,
      therapist_id: therapistId,
      day_of_week: input.day_of_week,
      start_time: input.start_time,
      end_time: input.end_time,
      is_active: input.is_active ?? true,
    })
    .select()
    .single()

  if (error) throw error
  return data
}

export async function updateAvailabilitySchedule(
  id: string,
  input: Partial<AvailabilityInput>
): Promise<AvailabilitySchedule> {
  const { data, error } = await supabase
    .from('availability_schedules')
    .update(input)
    .eq('id', id)
    .select()
    .single()

  if (error) throw error
  return data
}

export async function deleteAvailabilitySchedule(id: string): Promise<void> {
  const { error } = await supabase.from('availability_schedules').delete().eq('id', id)

  if (error) throw error
}

// ============================================================
// Availability Blocks (bloqueios pontuais de agenda)
// ============================================================

export interface AvailabilityBlock {
  id: string
  tenant_id: string
  therapist_id: string | null
  date: string // YYYY-MM-DD
  start_time: string | null // NULL = dia inteiro
  end_time: string | null
  reason: string | null
  created_at: string | null
}

export interface AvailabilityBlockInput {
  date: string
  start_time?: string | null
  end_time?: string | null
  reason?: string | null
}

export async function getAvailabilityBlocks(): Promise<AvailabilityBlock[]> {
  const tenantId = await getTenantId()
  if (!tenantId) return []
  const therapistId = await getCurrentUserId()

  const { data, error } = await supabase
    .from('availability_blocks')
    .select('*')
    .eq('tenant_id', tenantId)
    // Aba Agendamento: só os bloqueios PESSOAIS deste terapeuta.
    // Os bloqueios da conta (therapist_id = null) vivem na aba Conta.
    .eq('therapist_id', therapistId)
    .order('date')
    .order('start_time', { nullsFirst: true })

  if (error) throw error
  return data || []
}

export async function createAvailabilityBlock(
  input: AvailabilityBlockInput
): Promise<AvailabilityBlock> {
  const tenantId = await getTenantId()
  if (!tenantId) throw new Error('Tenant não encontrado')
  const therapistId = await getCurrentUserId()

  const { data, error } = await supabase
    .from('availability_blocks')
    .insert({
      tenant_id: tenantId,
      therapist_id: therapistId,
      date: input.date,
      start_time: input.start_time ?? null,
      end_time: input.end_time ?? null,
      reason: input.reason ?? null,
    })
    .select()
    .single()

  if (error) throw error
  return data
}

export async function deleteAvailabilityBlock(id: string): Promise<void> {
  const { error } = await supabase.from('availability_blocks').delete().eq('id', id)
  if (error) throw error
}

