// ============================================================
// Bookable Modules (módulos disponíveis para agendamento)
// ============================================================

export async function getBookableModules(): Promise<BookableModule[]> {
  const tenantId = await getTenantId()
  if (!tenantId) return []

  // Buscar todos os módulos ativos do tenant
  const { data: modules, error: modulesError } = await supabase
    .from('therapy_modules')
    .select('id, name, description, icon, color, active')
    .eq('tenant_id', tenantId)
    .eq('active', true)
    .order('display_order')

  if (modulesError) throw modulesError
  if (!modules?.length) return []

  // Buscar os booking_services vinculados a módulos
  const { data: services, error: servicesError } = await supabase
    .from('booking_services')
    .select('id, module_id, is_active, duration_minutes, buffer_minutes, price')
    .eq('tenant_id', tenantId)
    .not('module_id', 'is', null)

  if (servicesError) throw servicesError

  // Criar mapa de module_id -> booking_service
  const serviceByModule = new Map<string, BookableModule['booking_service']>()
  for (const svc of services || []) {
    if (svc.module_id) {
      serviceByModule.set(svc.module_id, {
        id: svc.id,
        is_active: svc.is_active,
        duration_minutes: svc.duration_minutes,
        buffer_minutes: svc.buffer_minutes,
        price: svc.price,
      })
    }
  }

  // Combinar
  return modules.map(mod => ({
    ...mod,
    booking_service: serviceByModule.get(mod.id) || null,
  }))
}

// Habilitar um módulo para agendamento online
export async function enableModuleForBooking(
  moduleId: string,
  config: { duration_minutes: number; buffer_minutes?: number; price?: number | null }
): Promise<BookingService> {
  const tenantId = await getTenantId()
  if (!tenantId) throw new Error('Tenant não encontrado')

  // Buscar dados do módulo
  const { data: module, error: moduleError } = await supabase
    .from('therapy_modules')
    .select('name, description, color')
    .eq('id', moduleId)
    .single()

  if (moduleError) throw moduleError

  // Criar booking_service vinculado ao módulo
  const { data, error } = await supabase
    .from('booking_services')
    .insert({
      tenant_id: tenantId,
      module_id: moduleId,
      name: module.name,
      description: module.description,
      color: module.color,
      duration_minutes: config.duration_minutes,
      buffer_minutes: config.buffer_minutes ?? 10,
      price: config.price ?? null,
      is_active: true,
    })
    .select()
    .single()

  if (error) throw error
  return data
}

// Desabilitar um módulo do agendamento
export async function disableModuleForBooking(moduleId: string): Promise<void> {
  const tenantId = await getTenantId()
  if (!tenantId) throw new Error('Tenant não encontrado')

  const { error } = await supabase
    .from('booking_services')
    .delete()
    .eq('tenant_id', tenantId)
    .eq('module_id', moduleId)

  if (error) throw error
}

// Atualizar configuração de booking de um módulo
export async function updateModuleBookingConfig(
  moduleId: string,
  config: {
    duration_minutes?: number
    buffer_minutes?: number
    price?: number | null
    is_active?: boolean
  }
): Promise<BookingService> {
  const tenantId = await getTenantId()
  if (!tenantId) throw new Error('Tenant não encontrado')

  const { data, error } = await supabase
    .from('booking_services')
    .update(config)
    .eq('tenant_id', tenantId)
    .eq('module_id', moduleId)
    .select()
    .single()

  if (error) throw error
  return data
}
