import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import {
  type AvailabilityBlockInput,
  type AvailabilityInput,
  type BookingServiceInput,
  createAccountBlock,
  createAvailabilityBlock,
  createAvailabilitySchedule,
  createBookingService,
  deleteAvailabilityBlock,
  deleteAvailabilitySchedule,
  deleteBookingService,
  disableModuleForBooking,
  enableModuleForBooking,
  getAccountBlocks,
  getAvailabilityBlocks,
  getAvailabilitySchedules,
  getBookableModules,
  getBookingServices,
  updateAvailabilitySchedule,
  updateBookingService,
  updateModuleBookingConfig,
} from '@/services/booking'
import { toast } from '@/lib/toast'

// ============================================================
// Availability Blocks (bloqueios pontuais)
// ============================================================

export function useAvailabilityBlocks() {
  return useQuery({
    queryKey: ['availability-blocks'],
    queryFn: getAvailabilityBlocks,
  })
}

export function useCreateAvailabilityBlock() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (input: AvailabilityBlockInput) => createAvailabilityBlock(input),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['availability-blocks'] })
      toast('Bloqueio adicionado!')
    },
    onError: () => toast('Erro ao adicionar bloqueio', 'error'),
  })
}

export function useDeleteAvailabilityBlock() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (id: string) => deleteAvailabilityBlock(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['availability-blocks'] })
      queryClient.invalidateQueries({ queryKey: ['account-blocks'] })
      toast('Bloqueio removido!')
    },
    onError: () => toast('Erro ao remover bloqueio', 'error'),
  })
}

